sys_ui_action.script:
function triggerServerExecution() {
    try {
        console.log('UI Action: triggerServerExecution started.');
        g_form.addInfoMessage('Executing script... please wait.');

        // Instantiate GlideAjax
        var ga = new GlideAjax('x_938076_now_utils.OAuthTokenGenerator');
        ga.addParam('sysparm_name', 'getOAuthTokenForm');

        // Grab and pass variables safely
        ga.addParam('sysparm_clientsecret', g_form.getValue('clientsecret') || '');
        ga.addParam('sysparm_clientid', g_form.getValue('client_id') || '');
        ga.addParam('sysparm_userName', g_form.getValue('user_id') || '');
        ga.addParam('sysparm_userPassword', g_form.getValue('password') || '');
        ga.addParam('sysparm_endPoint', g_form.getValue('end_point') || '');
        ga.addParam('sysparm_formID', g_form.getUniqueValue());
        ga.addParam('sysparm_tableName', g_form.getTableName());

        console.log('UI Action: Sending GlideAjax request now...');

        // Inline callback completely eliminates scoping/declaration bugs
        ga.getXMLAnswer(function(response) {
            console.log('UI Action: Server responded successfully.');
            g_form.clearMessages();
            g_form.addInfoMessage('Server Results: ' + response);

            try {
                var result = JSON.parse(response);
                if (result && !result.error) {
                    window.location.reload(); // Refresh to show tokens
                }
            } catch(e) {
                console.error('UI Action callback parse error: ' + e);
            }
        });

    } catch (err) {
        console.error('UI Action crashed before hitting server: ' + err.message);
        g_form.addErrorMessage('Client-side script error: ' + err.message);
    }
}
